const normalize=value=>String(value??'').normalize('NFKC').toLocaleLowerCase().replace(/\s+/g,' ').trim();
const matchesSubject=(item,subject)=>subject==='all'||item.subject===subject||item.subjects.includes(subject);
const matchesCategory=(item,category)=>category==='all'||item.category===category||item.topics.includes(canonicalCategory(category));
export function filterFormulaTemplates({subject='all',level='all',category='all',query=''}={}){
 const terms=normalize(query).split(' ').filter(Boolean);
 return formulaTemplates.filter(item=>matchesSubject(item,subject)&&(level==='all'||item.level===level||(level==='basic'&&['primary','junior'].includes(item.level))||(level==='advanced'&&['high','university'].includes(item.level)))&&matchesCategory(item,category)&&terms.every(term=>normalize([item.title,item.description,item.formula,item.category,...item.topics,...item.keywords].join(' ')).includes(term)));
}
export function formulaCategoryCounts({subject='all',level='all',query=''}={}){
 const rows=filterFormulaTemplates({subject,level,query}),subjects=subject==='all'?formulaSubjects.map(([value])=>value).filter(value=>value!=='all'):[subject],labels=[...new Set(subjects.flatMap(value=>{const taxonomy=formulaCategoryTaxonomy[value]||[],subjectRows=rows.filter(item=>matchesSubject(item,value)),extras=subjectRows.filter(item=>!item.topics.some(topic=>taxonomy.includes(topic))).map(item=>item.category);return [...taxonomy,...extras];}))];
 return labels.map(value=>({value,label:value,count:rows.filter(item=>matchesCategory(item,value)).length})).filter(item=>item.count>0);
}
export function formulaTemplateCategories(filters={}){return formulaCategoryCounts(filters).map(item=>item.value);}
export function paginateFormulaTemplates({page=1,pageSize=10,...filters}={}){
 const rows=filterFormulaTemplates(filters),size=Math.min(50,Math.max(1,Math.trunc(Number(pageSize))||10)),totalPages=Math.max(1,Math.ceil(rows.length/size)),current=Math.min(totalPages,Math.max(1,Math.trunc(Number(page))||1));
 return {items:rows.slice((current-1)*size,current*size),total:rows.length,totalPages,page:current,pageSize:size};
}
export function insertFormulaToken(text,token,start=String(text).length,end=start){text=String(text);start=Math.max(0,Math.min(text.length,Number(start)||0));end=Math.max(start,Math.min(text.length,Number(end)||0));const next=text.slice(0,start)+token+text.slice(end);const empty=token.indexOf('{}'),position=start+(empty>=0?empty+1:token.length);return {value:next,start:position,end:position};}

